package com.fitmind.scheduler; import com.fitmind.service.HealthLetterService; import lombok.RequiredArgsConstructor; import org.springframework.boot.context.event.ApplicationReadyEvent; import org.springframework.context.event.EventListener; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.time.*;
@Component @RequiredArgsConstructor public class HealthLetterScheduler { private final HealthLetterService service; @Scheduled(cron="0 0 6 * * ?",zone="Asia/Shanghai") public void daily(){service.generateToday();} @EventListener(ApplicationReadyEvent.class) public void compensate(){if(LocalTime.now(ZoneId.of("Asia/Shanghai")).isAfter(LocalTime.of(6,0)))service.generateToday();} }
